-- +migrate StatementBegin
CREATE FUNCTION automation.keep_live_platform_leases() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.platform AND OLD.lease_until > clock_timestamp()
        AND coalesce(current_setting('automation.release_platform', true), '') <> 'on' THEN
        RETURN NULL;
    END IF;
    RETURN OLD;
END;
$$;
-- +migrate StatementEnd

-- +migrate StatementBegin
CREATE FUNCTION automation.retire_platform_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.platform THEN
        INSERT INTO automation.retired_platform_identities (kind, external, stray_key) VALUES (OLD.kind, OLD.external, OLD.stray_key)
        ON CONFLICT (kind, external) DO UPDATE
            SET retired_at = now(), stray_key = coalesce(EXCLUDED.stray_key, automation.retired_platform_identities.stray_key);
    END IF;
    RETURN OLD;
END;
$$;
-- +migrate StatementEnd

-- +migrate StatementBegin
CREATE FUNCTION extruntime.forbid_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'extruntime.% rows are immutable', TG_TABLE_NAME USING ERRCODE = 'restrict_violation';
END;
$$;
-- +migrate StatementEnd

-- +migrate StatementBegin
CREATE FUNCTION public.action_logs_events_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.event_type IS NULL OR NOT EXISTS (
            SELECT
                1
            FROM
                tenants
            WHERE
                id = OLD.tenant_id) THEN
            RETURN OLD;
        END IF;
    ELSIF OLD.event_type IS NULL
            AND NEW.event_type IS NULL THEN
            RETURN NEW;
    END IF;
    RAISE EXCEPTION 'action_logs events are append-only';
END;
$$;
-- +migrate StatementEnd

-- +migrate StatementBegin
CREATE TABLE public.action_logs (
    id bigint NOT NULL,
    method character varying(255),
    path character varying(255),
    user_id bigint,
    after jsonb,
    before jsonb,
    user_agent character varying(255),
    ip character varying(255),
    created_at timestamp with time zone DEFAULT now(),
    tenant_id uuid DEFAULT '00000000-0000-0000-0000-000000000001'::uuid NOT NULL,
    event_id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_type character varying(200),
    schema_version integer,
    category character varying(20),
    occurred_at timestamp with time zone,
    actor_kind character varying(20),
    actor_id character varying(255),
    actor_snapshot jsonb,
    initiator_snapshot jsonb,
    channel character varying(20),
    operation_id character varying(255),
    request_id character varying(255),
    run_id character varying(255),
    client_id character varying(255),
    outcome character varying(20),
    resources text[] DEFAULT '{}'::text[] NOT NULL,
    subject_refs text[] DEFAULT '{}'::text[] NOT NULL,
    subjects jsonb DEFAULT '[]'::jsonb NOT NULL,
    changes jsonb DEFAULT '[]'::jsonb NOT NULL,
    fingerprint character varying(64),
    CONSTRAINT action_logs_actor_kind_check CHECK ((actor_kind IN ('user', 'service', 'system'))),
    CONSTRAINT action_logs_category_check CHECK ((category IN ('business', 'security'))),
    CONSTRAINT action_logs_channel_check CHECK ((channel IN ('ui', 'mcp', 'chat', 'import', 'job', 'api'))),
    CONSTRAINT action_logs_event_complete CHECK (((event_type IS NULL) OR ((schema_version IS NOT NULL) AND (category IS NOT NULL) AND (occurred_at IS NOT NULL) AND (created_at IS NOT NULL) AND (actor_kind IS NOT NULL) AND (actor_id IS NOT NULL) AND (actor_snapshot IS NOT NULL) AND (channel IS NOT NULL) AND (operation_id IS NOT NULL) AND (outcome IS NOT NULL) AND (fingerprint IS NOT NULL)))),
    CONSTRAINT action_logs_legacy_request CHECK (((event_type IS NOT NULL) OR ((method IS NOT NULL) AND (path IS NOT NULL) AND (user_agent IS NOT NULL) AND (ip IS NOT NULL)))),
    CONSTRAINT action_logs_outcome_check CHECK ((outcome IN ('succeeded', 'failed', 'denied'))),
    CONSTRAINT action_logs_schema_version_check CHECK ((schema_version > 0))
);
-- +migrate StatementEnd

COMMENT ON TABLE public.action_logs IS 'Business action history. Rows without event_type are legacy request-log records.';

-- +migrate StatementBegin
CREATE VIEW analytics.action_logs AS
 SELECT id,
    method,
    path,
    user_id,
    after,
    before,
    user_agent,
    ip,
    created_at,
    tenant_id
   FROM public.action_logs
  WHERE ((tenant_id = (current_setting('app.tenant_id'::text, true))::uuid) AND (event_type IS NULL));
